public function __invoke(PlaceOrder $cmd): void
{
    $this->em->wrapInTransaction(function () use ($cmd): void {
        $order = Order::place($cmd->customerId, $cmd->lines);
        $this->em->persist($order);

        $event = new OrderPlaced((string) Uuid::v7(), $order->getId(), $cmd->lines);
        $this->em->persist(new OutboxMessage(
            id: $event->messageId,
            type: OrderPlaced::class,
            payload: $this->serializer->serialize($event, 'json'),
        ));
    });                                  // both commit together
}

public function publishBatch(int $limit = 50): int
{
    return $this->db->transactional(function () use ($limit): int {
        $rows = $this->db->fetchAllAssociative(
            "SELECT id, type, payload FROM outbox WHERE sent_at IS NULL
             ORDER BY created_at LIMIT $limit FOR UPDATE SKIP LOCKED"
        );
        foreach ($rows as $r) {
            $message = $this->serializer->deserialize($r['payload'], $r['type'], 'json');
            $this->bus->dispatch($message);          // a real broker transport
            $this->db->update('outbox', ['sent_at' => date('c')], ['id' => $r['id']]);
        }

        return count($rows);
    });
}

CREATE TABLE outbox (
    id          uuid PRIMARY KEY,
    type        varchar(255) NOT NULL,
    payload     jsonb NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    sent_at     timestamptz NULL
);
-- the relay only ever asks for unsent rows
CREATE INDEX outbox_unsent ON outbox (created_at) WHERE sent_at IS NULL;

-- housekeeping, daily: sent rows are only history
DELETE FROM outbox WHERE sent_at < now() - interval '7 days';

CREATE TABLE inbox (
    message_id  uuid NOT NULL,
    handler     varchar(255) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (message_id, handler)
);
-- housekeeping: forget ids older than any duplicate can be
DELETE FROM inbox WHERE received_at < now() - interval '14 days';

