#[ORM\Entity]
class OrderSaga
{
    #[ORM\Id, ORM\Column(type: 'uuid')]
    private Uuid $orderId;

    #[ORM\Column(length: 20)]
    private string $step = 'started';   // started → paid → reserved → completed
                                        // on failure: compensating → cancelled
    #[ORM\Column]
    private \DateTimeImmutable $deadline;

    #[ORM\Column(nullable: true)]
    private ?string $failure = null;

    public function step(): string { return $this->step; }
    public function moveTo(string $step): void { $this->step = $step; }
}

#[AsMessageHandler]
public function onPaid(PaymentCharged $e): void
{
    $saga = $this->sagas->find($e->orderId);
    if ('started' !== $saga->step()) {
        return;                                      // duplicate event
    }
    $saga->moveTo('paid');
    $this->em->flush();
    $this->bus->dispatch(new ReserveStock($e->orderId));
}

#[AsMessageHandler]
public function onCourierFailed(CourierBookingFailed $e): void
{
    $this->sagas->find($e->orderId)->moveTo('compensating');
    $this->em->flush();
    $this->bus->dispatch(new ReleaseStock($e->orderId));   // stock first
}

#[AsMessageHandler]
public function onStockReleased(StockReleased $e): void
{
    $this->bus->dispatch(new RefundPayment($e->orderId));  // then the money
}

#[AsPeriodicTask(frequency: '1 minute', schedule: 'default')]
final readonly class SagaTimeoutSweeper
{
    public function __invoke(): void
    {
        $ids = $this->db->fetchFirstColumn(
            "SELECT order_id FROM order_saga
             WHERE step IN ('started', 'paid', 'reserved') AND deadline < now()"
        );
        foreach ($ids as $id) {
            $this->bus->dispatch(new SagaTimedOut($id));  // the orchestrator picks it up
        }
    }
}

#[AsMessageHandler]
public function onTimedOut(SagaTimedOut $e): void
{
    $saga = $this->sagas->find($e->orderId);
    if (!\in_array($saga->step(), ['started', 'paid', 'reserved'], true)) {
        return;                          // already compensating: duplicate sweep
    }
    $saga->moveTo('compensating');
    $this->em->flush();
    // the courier step may have worked: cancel it too, by its own key
    $this->bus->dispatch(new CancelCourierBooking($e->orderId, 'book-'.$e->orderId));
}

#[AsMessageHandler]
public function onCourierCancelled(CourierBookingCancelled $e): void
{
    $this->bus->dispatch(new ReleaseStock($e->orderId));   // then stock, then money
}

#[AsMessageHandler]
public function __invoke(CancelCourierBooking $c): void
{
    $booking = $this->bookings->findByKey($c->key);
    if (null === $booking) {
        // never arrived, or still on its way: leave a canceled marker,
        // so a late BookCourier with this key is refused
        $this->bookings->save(Booking::cancelled($c->key));
    } else {
        $booking->cancel();              // already canceled? nothing changes
    }
    $this->bus->dispatch(new CourierBookingCancelled($c->orderId));
}

public function refund(Payment $payment, int $amount): void
{
    $payment->setAmount($payment->getAmount() - $amount);   // overwrites the original
    $this->em->flush();
    $this->gateway->refund($payment->getGatewayId(), $amount);
}

public function refund(Uuid $paymentId, int $amount, string $reason, string $key): Refund
{
    return $this->em->wrapInTransaction(function () use ($paymentId, $amount, $reason, $key) {
        $payment = $this->em->find(Payment::class, $paymentId, LockMode::PESSIMISTIC_WRITE);

        $same = $this->refunds->findOneBy(['payment' => $payment, 'idemKey' => $key]);
        if (null !== $same) {
            return $same;                       // the same request again
        }
        $remaining = $payment->getAmount() - $this->refunds->totalFor($payment);
        if ($amount <= 0 || $amount > $remaining) {
            throw new RefundExceedsPayment($remaining);
        }
        $refund = new Refund($payment, $amount, $reason, $key);
        $this->em->persist($refund);
        $this->outbox->add(new RefundRequested($refund->getId()));   // gateway call comes later

        return $refund;
    });
}

final readonly class RefundFeePolicy
{
    public function __construct(
        private RefundFeeRuleRepository $rules,   // reads the refund_fee_rule table
        private ExpressionLanguage $expr,
    ) {}

    /** @param array<string, mixed> $facts e.g. ['days' => 9, 'reason' => 'changed_mind'] */
    public function feeFor(int $amount, array $facts): Fee
    {
        foreach ($this->rules->activeInOrder() as $rule) {
            if ($this->expr->evaluate($rule->when, $facts)) {
                return new Fee(intdiv($amount * $rule->bp, 10_000), $rule->name);
            }
        }

        return new Fee(0, 'no-fee');
    }
}

final class Account
{
    private int $balance = 0;
    private int $version = 0;
    private array $pending = [];

    public static function fromHistory(iterable $events): self
    {
        $a = new self();
        foreach ($events as $e) { $a->apply($e); }     // only builds state

        return $a;
    }

    public function withdraw(int $amount): void
    {
        if ($amount > $this->balance) {
            throw new InsufficientFunds($this->balance);
        }
        $this->apply($e = new MoneyWithdrawn($amount));
        $this->pending[] = $e;                         // waiting to be saved
    }

    private function apply(object $e): void
    {
        match ($e::class) {
            MoneyDeposited::class => $this->balance += $e->amount,
            MoneyWithdrawn::class => $this->balance -= $e->amount,
        };
        ++$this->version;
    }
}

public function append(Uuid $id, int $expectedVersion, array $events): void
{
    try {
        $this->db->transactional(function () use ($id, $expectedVersion, $events): void {
            foreach (array_values($events) as $i => $e) {
                $this->db->insert('event_store', [
                    'aggregate_id' => $id->toRfc4122(),
                    'version' => $expectedVersion + $i + 1,
                    'type' => $e::class,
                    'schema_v' => 1,
                    'payload' => $this->serializer->serialize($e, 'json'),
                ]);
            }
        });
    } catch (UniqueConstraintViolationException) {
        throw new ConcurrentModification($id);   // someone else wrote first
    }
}

public function load(Uuid $id): Account
{
    $snap = $this->db->fetchAssociative(
        'SELECT version, balance FROM account_snapshot WHERE aggregate_id = ?',
        [$id->toRfc4122()],
    ) ?: ['version' => 0, 'balance' => 0];

    $later = $this->store->eventsAfter($id, (int) $snap['version']);

    return Account::restore((int) $snap['balance'], (int) $snap['version'], $later);
}

public function saveSnapshot(Uuid $id, Account $a): void     // every 100th event
{
    $this->db->executeStatement(
        'INSERT INTO account_snapshot (aggregate_id, version, balance) VALUES (?, ?, ?)
         ON CONFLICT (aggregate_id) DO UPDATE
         SET version = EXCLUDED.version, balance = EXCLUDED.balance',
        [$id->toRfc4122(), $a->version(), $a->balance()],
    );
}

public static function restore(int $balance, int $version, iterable $later): self
{
    $a = new self();
    $a->balance = $balance;
    $a->version = $version;
    foreach ($later as $e) { $a->apply($e); }    // the same apply() as before

    return $a;
}

#[AsMessageHandler]
final readonly class AccountBalanceProjector
{
    public function __construct(private Connection $db) {}

    public function __invoke(AccountEventRecorded $m): void
    {
        $this->db->executeStatement(
            'INSERT INTO account_balance (account_id, balance, version)
             VALUES (:id, :delta, :v)
             ON CONFLICT (account_id) DO UPDATE
             SET balance = account_balance.balance + :delta, version = :v
             WHERE account_balance.version = :v - 1',
            ['id' => $m->aggregateId, 'delta' => $m->signedAmount, 'v' => $m->version],
        );                                  // 0 rows: a duplicate or out-of-order event
    }
}

final class MoneyDepositedUpcaster
{
    public function upcast(array $payload, int $schemaV): array
    {
        if (1 === $schemaV) {            // v1 had no currency: all US dollars
            $payload['currency'] = 'USD';
            $schemaV = 2;
        }
        // when v2 → v3 arrives, another if goes here

        return $payload;                 // always in the latest shape
    }
}
